import { cx } from '~/lib/cx'
import { Dropdown, type DropdownItem } from './dropdown'
import styles from './menubar.module.scss'

export interface MenubarMenu {
  label: string
  items: DropdownItem[]
}

export interface MenubarProps {
  menus: MenubarMenu[]
  align?: 'left' | 'right'
  className?: string
  label?: string
}

/** Horizontal application menu. Each menu reuses the viewport-aware Dropdown. */
export function Menubar({
  menus,
  align = 'left',
  className,
  label = 'Application menu',
}: MenubarProps) {
  return (
    <div role="group" aria-label={label} className={cx(styles.root, className)}>
      {menus.map((menu) => (
        <Dropdown
          key={menu.label}
          align={align}
          items={menu.items}
          trigger={
            <button type="button" className={styles.trigger}>
              {menu.label}
            </button>
          }
        />
      ))}
    </div>
  )
}

@use 'styles' as vz;

.root {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 3px;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('lg');
  background: vz.color('card');
}

.trigger {
  height: 1.875rem;
  padding-inline: vz.space(2.5);
  border: 0;
  border-radius: vz.radius('sm');
  background: transparent;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  font-weight: 500;
  cursor: pointer;

  @include vz.hover {
    background: vz.color('accent');
    color: vz.color('accent-foreground');
  }

  @include vz.focus-ring(2px, 1px, 0.6);
}
